values ('ap_biology', 2, '2.3', array['2.3']::text[], 'diagram', 'Fluid mosaic model of the plasma membrane', 'Labelled parts of the membrane diagram students must read and describe.', '[{"label": "Phospholipid bilayer", "meaning": "Hydrophilic phosphate regions face aqueous surroundings; hydrophobic fatty acid tails face each other in the interior"}, {"label": "Embedded proteins", "meaning": "Hydrophilic, hydrophobic, or both; hydrophobic regions contact the fatty acids"}, {"label": "Steroids (e.g., cholesterol in vertebrate animals)", "meaning": "Embedded in the phospholipid framework"}, {"label": "Glycoproteins", "meaning": "Embedded components that move within the membrane"}, {"label": "Glycolipids", "meaning": "Embedded components that move within the membrane"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-biology-reference-u1-u3-2026-10-10; candidate=ap_biology-u2-r1-025; ced=2.3.B.1 "phospholipid molecules embedded with proteins, steroids (such as cholesterol in vertebrate animals), glycoproteins, and glycolipids"')
