values ('ap_biology', 2, '2.3', array['2.3', '2.4']::text[], 'convention', 'Phospholipid orientation in the membrane', 'The polar hydrophilic phosphate regions face the aqueous external or internal environment, while the nonpolar hydrophobic fatty acid regions face each other in the membrane interior.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-biology-reference-u1-u3-2026-10-10; candidate=ap_biology-u2-r1-022; ced=2.3.A.1 "nonpolar hydrophobic fatty acid regions face each other within the interior of the membrane"')
