insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_biology', 2, '2.4', array['2.4']::text[], 'vocabulary', 'Cell wall', 'In Bacteria, Archaea, Fungi, and plants, the cell wall provides a structural boundary, a permeability barrier for some substances, and protection from osmotic lysis.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-biology-reference-u1-u3-2026-10-10; candidate=ap_biology-u2-r2-004; ced=EK 2.4.B.1: "provide a structural boundary as well as a permeability barrier for some substances ... and protection from osmotic lysis"')
