insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_biology', 2, '2.4', array['2.4', '2.5']::text[], 'vocabulary', 'Selective permeability', 'The property of the plasma membrane, resulting from its hydrophobic interior, that lets some substances cross while restricting others.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-biology-reference-u1-u3-2026-10-10; candidate=ap_biology-u2-r1-026; ced=2.4.A.1 "Selective permeability is the result of the plasma membrane having a hydrophobic interior"')
