values ('ap_biology', 2, '2.5', array['2.5']::text[], 'vocabulary', 'Endocytosis', 'An energy-requiring process in which the cell takes in large molecules and particulate matter by folding the plasma membrane in on itself and forming small vesicles that engulf material from the external environment.', '[]'::jsonb, NULL, 'Endocytosis and exocytosis both require energy to move large substances into and out of cells.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-biology-reference-u1-u3-2026-10-10; candidate=ap_biology-u2-r1-031; ced=2.5.B.1.i "folding the plasma membrane in on itself and forming new (small) vesicles"')
