values ('ap_biology', 2, '2.6', array['2.6']::text[], 'vocabulary', 'Facilitated diffusion', 'Facilitated diffusion uses transport or channel proteins to move charged ions and large polar molecules across the membrane down their concentration gradient with no energy input.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-biology-reference-u1-u3-2026-10-10; candidate=ap_biology-u2-r2-006; ced=EK 2.6.A.1-2: "requires transport or channel proteins"; "movement of large polar molecules through membranes with no energy input"')
