values ('ap_biology', 2, '2.7', array['2.7']::text[], 'convention', 'Direction of osmosis', 'Water moves by osmosis from regions of high water potential to regions of low water potential, which is the same as moving from low solute concentration (low osmolarity) to high solute concentration (high osmolarity).', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-biology-reference-u1-u3-2026-10-10; candidate=ap_biology-u2-r1-036; ced=2.7.A.1 and 2.7.B.2 "from regions of low osmolarity or solute concentration to regions of high osmolarity"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
